#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(data.table);library(hdf5r)})
r<-'paper19opp-revision2/reconstruction';out<-file.path(r,'external_resources');started<-Sys.time()
upr<-fread(file.path(r,'cross_dataset/final_axis_membership.tsv'))[program=='hallmark_UNFOLDED_PROTEIN_RESPONSE'&in_common==TRUE,gene];universe<-fread(file.path(r,'cross_dataset/final_gene_universe.tsv'))$gene
ann<-function(f,g,n){o<-f[[g]][[n]];if(inherits(o,'H5Group'))return(o[['categories']][][o[['codes']][]+1L]);o[]}
# Adamson CSR matrix: one pass stores only raw UPR and fixed-cohort target columns.
x<-fread(file.path(r,'candidate_validation/adamson_cell_scores_harmonized.tsv.gz'));gset<-fread(file.path(r,'candidate_validation/harmonized_adamson_candidates.tsv'))$gene;wantedgenes<-unique(c(upr,gset))
f<-H5File$new('/Volumes/wang/paper4rfv/data/processed/h5ad/core_unpacked/adamson_2016_upr__GSM2406681_10X010.h5ad','r');genes<-as.character(ann(f,'var','_index'));ids<-as.character(ann(f,'obs','_index'));stopifnot(identical(x$cell_id,ids),!anyDuplicated(genes),all(upr%in%genes));ptr<-f[['X']][['indptr']][];wi<-match(wantedgenes,genes);raw<-matrix(0,nrow(x),length(wantedgenes),dimnames=list(NULL,wantedgenes));raw[,is.na(wi)]<-NA_real_
for(st in seq.int(1,nrow(x),by=2000L)){en<-min(st+1999L,nrow(x));pp<-ptr[st:(en+1L)];ix<-seq.int(pp[1]+1,tail(pp,1));jj<-f[['X']][['indices']][ix]+1L;vv<-f[['X']][['data']][ix];rr<-rep(seq.int(st,en),diff(pp));cc<-match(jj,wi);ok<-!is.na(cc);stopifnot(!anyDuplicated(paste(rr[ok],cc[ok])));raw[cbind(rr[ok],cc[ok])]<-vv[ok]}
f$close_all();cells<-x[,.(cell_id,gene,context,is_control,common_library=library_size,original_UPR=score_hallmark_UNFOLDED_PROTEIN_RESPONSE)];ru<-raw[,upr,drop=FALSE];stopifnot(max(abs(rowMeans(log1p(1e4*ru/cells$common_library))-cells$original_UPR))<1e-10)
saveRDS(list(study='Adamson2016',cells=cells,raw_upr=ru,raw_target=raw[,gset,drop=FALSE],target_genes=gset,universe=universe),file.path(out,'adamson_UPR_raw_cache.rds'),compress='gzip');cat('Adamson cached elapsed',as.numeric(difftime(Sys.time(),started,units='secs')),'seconds\n');flush.console();rm(raw,ru,x);gc()
# Frangieh CSC columns: raw genes are unique, exact matched universe is already fixed.
x<-fread(file.path(r,'candidate_validation/frangieh_cell_scores_harmonized.tsv.gz'));gset<-fread(file.path(r,'candidate_validation/harmonized_frangieh_candidates.tsv'))$gene;wantedgenes<-unique(c(upr,gset));f<-H5File$new('/Volumes/wang/paper13/raw/perturbation/SCP1064/FrangiehIzar2021_RNA.h5ad','r');genes<-ann(f,'var','gene_symbol');ids<-ann(f,'obs','cell_name');ri<-match(x$cell_id,ids);stopifnot(!anyNA(ri),!anyDuplicated(genes),all(upr%in%genes));ptr<-f[['X']][['indptr']][];raw<-matrix(NA_real_,nrow(x),length(wantedgenes),dimnames=list(NULL,wantedgenes))
for(k in seq_along(wantedgenes)){j<-match(wantedgenes[k],genes);if(is.na(j))next;v<-numeric(length(ids));lo<-ptr[j]+1;hi<-ptr[j+1L];if(hi>=lo)v[f[['X']][['indices']][lo:hi]+1L]<-f[['X']][['data']][lo:hi];raw[,k]<-v[ri]};f$close_all();cells<-x[,.(cell_id,gene,context,is_control,common_library=library_size_common,original_UPR=score_hallmark_UNFOLDED_PROTEIN_RESPONSE)];ru<-raw[,upr,drop=FALSE];stopifnot(max(abs(rowMeans(log1p(1e4*ru/cells$common_library))-cells$original_UPR))<1e-10)
saveRDS(list(study='Frangieh2021',cells=cells,raw_upr=ru,raw_target=raw[,gset,drop=FALSE],target_genes=gset,universe=universe),file.path(out,'frangieh_UPR_raw_cache.rds'),compress='gzip');cat('Frangieh cached elapsed',as.numeric(difftime(Sys.time(),started,units='secs')),'seconds\n')
